topics.codeExample:
public class ParadigmComparison {
    // Domain object encapsulating account state & operations
    static class Account {
        private final String accountNumber;
        private double balance;

        public Account(String accNo, double initialBalance) {
            this.accountNumber = accNo;
            this.balance = Math.max(0.0, initialBalance);
        }

        public void deposit(double amount) {
            if (amount > 0) {
                this.balance += amount;
                System.out.println("Deposited $" + amount + ", Balance: $" + this.balance);
            }
        }

        public double getBalance() {
            return this.balance;
        }
    }

    public static void main(String[] args) {
        Account acc = new Account("ACC-9821", 500.0);
        acc.deposit(250.0);
        System.out.println("Final verified balance: $" + acc.getBalance());
    }
}

