topics.codeExample:
public class VariableScopeDemo {
    static class BankCustomer {
        String customerName;
        double accountBalance;

        void transfer(BankCustomer recipient, double amount) {
            // amount is local to transfer method call
            if (this.accountBalance >= amount) {
                this.accountBalance -= amount;
                recipient.accountBalance += amount;
                System.out.println("Transferred $" + amount + " from " + this.customerName + " to " + recipient.customerName);
            }
        }
    }

    public static void main(String[] args) {
        BankCustomer c1 = new BankCustomer();
        c1.customerName = "Elena";
        c1.accountBalance = 1000.0;

        BankCustomer c2 = new BankCustomer();
        c2.customerName = "Marcus";
        c2.accountBalance = 250.0;

        c1.transfer(c2, 300.0);
        System.out.println(c1.customerName + " Balance: $" + c1.accountBalance);
        System.out.println(c2.customerName + " Balance: $" + c2.accountBalance);
    }
}

