topics.codeExample:
public class CleanConstructorChaining {
    static class BankCustomer {
        String id;
        String name;
        String tier;
        double creditLimit;

        // 1. Minimum details constructor
        public BankCustomer(String id, String name) {
            this(id, name, "STANDARD", 1000.0);
        }

        // 2. Custom tier constructor
        public BankCustomer(String id, String name, String tier) {
            this(id, name, tier, tier.equals("VIP") ? 10000.0 : 2500.0);
        }

        // 3. Master constructor: Centralized validation and assignment
        public BankCustomer(String id, String name, String tier, double creditLimit) {
            this.id = id;
            this.name = name;
            this.tier = tier;
            this.creditLimit = creditLimit;
        }

        void printProfile() {
            System.out.println(id + " | " + name + " | Tier: " + tier + " | Limit: $" + creditLimit);
        }
    }

    public static void main(String[] args) {
        BankCustomer c1 = new BankCustomer("C-01", "Jordan");
        BankCustomer c2 = new BankCustomer("C-02", "Valerie", "VIP");
        c1.printProfile();
        c2.printProfile();
    }
}

