import java.util.HashMap;
import java.util.Map;

public class ComplexStaticInit {
    static class CurrencyConverter {
        private static final Map<String, Double> EXCHANGE_RATES = new HashMap<>();

        // Static initialization block for complex pre-population
        static {
            EXCHANGE_RATES.put("EUR", 1.08);
            EXCHANGE_RATES.put("GBP", 1.26);
            EXCHANGE_RATES.put("JPY", 0.0067);
            System.out.println("Exchange rates loaded successfully: " + EXCHANGE_RATES.size() + " currencies");
        }

        public static double convertToUSD(double amount, String currency) {
            return amount * EXCHANGE_RATES.getOrDefault(currency, 1.0);
        }
    }

    public static void main(String[] args) {
        System.out.println("Converting 100 EUR to USD: $" + CurrencyConverter.convertToUSD(100.0, "EUR"));
    }
}

