topics.codeExample:
public class GarbageCollectionEligibility {
    static class HeavyPayload {
        int id;
        byte[] data = new byte[1024]; // 1KB

        HeavyPayload(int id) {
            this.id = id;
        }
    }

    static HeavyPayload createScoped() {
        HeavyPayload temp = new HeavyPayload(99); // Scope-bound
        return temp; // Escapes method scope via return
    }

    public static void main(String[] args) {
        HeavyPayload p1 = new HeavyPayload(1);
        HeavyPayload p2 = new HeavyPayload(2);

        // 1. Reassignment
        p1 = p2; // Original payload 1 is now unreachable

        // 2. Nulling reference
        HeavyPayload p3 = createScoped();
        p3 = null; // Payload 99 is now unreachable

        System.out.println("P2 Active: ID " + p2.id);
    }
}

