topics.codeExample:
public class BankAccountEncapsulation {
    static class BankAccount {
        private final String accountNumber;
        private double balance;

        public BankAccount(String accNo, double initialBalance) {
            this.accountNumber = accNo;
            this.balance = Math.max(0.0, initialBalance);
        }

        public boolean withdraw(double amount) {
            if (amount > 0 && amount <= this.balance) {
                this.balance -= amount;
                System.out.println("Withdrawal of $" + amount + " approved");
                return true;
            }
            System.out.println("Withdrawal of $" + amount + " declined: insufficient funds");
            return false;
        }

        public double getBalance() {
            return this.balance;
        }
    }

    public static void main(String[] args) {
        BankAccount acc = new BankAccount("BA-500", 300.0);
        acc.withdraw(100.0);
        acc.withdraw(500.0); // Safely rejected!
        System.out.println("Remaining balance: $" + acc.getBalance());
    }
}

