public class DefensiveCopyingDemo {
    static class BankTransaction {
        private final String txId;
        private double amount;
        private boolean settled;

        public BankTransaction(String id, double amount) {
            this.txId = id;
            setAmount(amount);
        }

        // Read-only property: No setter for txId
        public String getTxId() {
            return txId;
        }

        public double getAmount() {
            return amount;
        }

        public void setAmount(double amount) {
            if (settled) {
                throw new IllegalStateException("Cannot modify settled transaction");
            }
            if (amount <= 0) {
                throw new IllegalArgumentException("Amount must be positive");
            }
            this.amount = amount;
        }

        public boolean isSettled() { return settled; }
        public void markSettled() { this.settled = true; }
    }

    public static void main(String[] args) {
        BankTransaction tx = new BankTransaction("TX-99", 450.0);
        tx.setAmount(500.0); // Valid
        tx.markSettled();
        System.out.println(tx.getTxId() + " Amount: $" + tx.getAmount() + " Settled: " + tx.isSettled());
    }
}

