topics.codeExample:
public class RobustAccountInvariant {
    static class CheckingAccount {
        private final String accountId;
        private double balance;
        private final double maxOverdraft;

        public CheckingAccount(String accountId, double initialDeposit, double maxOverdraft) {
            if (accountId == null || accountId.trim().isEmpty()) {
                throw new IllegalArgumentException("Account ID cannot be blank");
            }
            if (maxOverdraft < 0) {
                throw new IllegalArgumentException("Overdraft limit cannot be negative");
            }
            this.accountId = accountId;
            this.maxOverdraft = maxOverdraft;
            this.balance = initialDeposit;
            assertInvariant();
        }

        public void withdraw(double amount) {
            if (amount <= 0) throw new IllegalArgumentException("Withdrawal must be positive");
            if (this.balance - amount < -this.maxOverdraft) {
                throw new IllegalStateException("Transaction exceeds permitted overdraft limit");
            }
            this.balance -= amount;
            assertInvariant();
            System.out.println("Withdrew $" + amount + ", Balance is now: $" + this.balance);
        }

        private void assertInvariant() {
            if (this.balance < -this.maxOverdraft) {
                throw new IllegalStateException("CRITICAL: Account invariant violated!");
            }
        }
    }

    public static void main(String[] args) {
        CheckingAccount acc = new CheckingAccount("CHK-881", 200.0, 100.0);
        acc.withdraw(250.0); // Leaves balance at -50.0 (within 100 overdraft)
    }
}

