public class MethodHidingPitfall {
    static class ConfigurationLoader {
        static String getEnvironment() { return "PRODUCTION"; }
        String getDbUrl() { return "jdbc:prod-cluster"; }
    }

    static class StagingLoader extends ConfigurationLoader {
        // Method Hiding: does NOT override static method!
        static String getEnvironment() { return "STAGING"; }
        @Override String getDbUrl() { return "jdbc:staging-db"; }
    }

    public static void main(String[] args) {
        ConfigurationLoader loader = new StagingLoader();

        // Tricky interview scenario:
        System.out.println("Environment: " + loader.getEnvironment()); // Prints PRODUCTION!
        System.out.println("DB URL: " + loader.getDbUrl());           // Prints jdbc:staging-db!

        // Best Practice: Always invoke static methods directly on Class name:
        System.out.println("Direct Static: " + StagingLoader.getEnvironment());
    }
}

