class MemoryStorage extends AbstractStorageEngine {
    private java.util.Map<String, String> map = new java.util.HashMap<>();
    @Override
    public void save(String key, String value) {
        validateKey(key);
        map.put(key, value);
        System.out.println("Saved: " + key + " = " + value);
    }
    @Override
    public String get(String key) {
        validateKey(key);
        return map.get(key);
    }
}

