import java.util.ArrayList;
import java.util.List;

class Professor {
    private String name;
    public Professor(String name) { this.name = name; }
    public String getName() { return name; }
}

class Department {
    private String deptName;
    private List<Professor> professors;

    // Aggregation: professors are passed in from outside
    public Department(String deptName, List<Professor> professors) {
        this.deptName = deptName;
        this.professors = professors;
    }

    public void showStaff() {
        System.out.println("Department: " + deptName);
        for (Professor p : professors) {
            System.out.println(" - Prof. " + p.getName());
        }
    }
}

public class AggregationDemo {
    public static void main(String[] args) {
        Professor p1 = new Professor("Snape");
        Professor p2 = new Professor("McGonagall");
        List<Professor> staff = new ArrayList<>();
        staff.add(p1);
        staff.add(p2);

        Department dept = new Department("Magic", staff);
        dept.showStaff();
        // Even if dept becomes null, p1 and p2 remain accessible
    }
}

