import java.util.*;

interface Borrowable {
    String getId();
    String getTitle();
    boolean isAvailable();
    void setAvailable(boolean available);
}

class Book implements Borrowable {
    private String id;
    private String title;
    private String author;
    private boolean available = true;

    public Book(String id, String title, String author) {
        this.id = id;
        this.title = title;
        this.author = author;
    }

    public String getId() { return id; }
    public String getTitle() { return title; }
    public boolean isAvailable() { return available; }
    public void setAvailable(boolean available) { this.available = available; }
}

abstract class Member {
    private String id;
    private String name;
    private List<Borrowable> borrowedItems = new ArrayList<>();

    public Member(String id, String name) {
        this.id = id;
        this.name = name;
    }

    public String getId() { return id; }
    public String getName() { return name; }
    public List<Borrowable> getBorrowedItems() { return borrowedItems; }

    public abstract int getMaxBorrowLimit();
    public abstract double getDailyFine();

    public boolean canBorrow() {
        return borrowedItems.size() < getMaxBorrowLimit();
    }
}

class StudentMember extends Member {
    public StudentMember(String id, String name) { super(id, name); }
    @Override public int getMaxBorrowLimit() { return 3; }
    @Override public double getDailyFine() { return 1.00; }
}

class FacultyMember extends Member {
    public FacultyMember(String id, String name) { super(id, name); }
    @Override public int getMaxBorrowLimit() { return 10; }
    @Override public double getDailyFine() { return 0.25; }
}

class Library {
    private Map<String, Book> books = new HashMap<>();
    private Map<String, Member> members = new HashMap<>();

    public void addBook(Book book) { books.put(book.getId(), book); }
    public void registerMember(Member member) { members.put(member.getId(), member); }

    public boolean borrowBook(String memberId, String bookId) {
        Member m = members.get(memberId);
        Book b = books.get(bookId);
        if (m == null || b == null) return false;
        if (!b.isAvailable() || !m.canBorrow()) return false;

        b.setAvailable(false);
        m.getBorrowedItems().add(b);
        System.out.println(m.getName() + " borrowed '" + b.getTitle() + "'");
        return true;
    }
}

public class LibraryApplication {
    public static void main(String[] args) {
        Library lib = new Library();
        lib.addBook(new Book("B01", "Effective Java", "Joshua Bloch"));
        lib.addBook(new Book("B02", "Clean Architecture", "Robert Martin"));

        Member student = new StudentMember("S01", "Bob");
        lib.registerMember(student);

        lib.borrowBook("S01", "B01");
    }
}

